```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input in the shared store (granted by the graph author).
        state_rw::put("last-input", &feed_url);

        let seconds = wall_clock::now().seconds;

        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat at {}s: fetched {} chars", seconds, fetched);
        let notified = notifier::notify(&message);

        // Contract: every output must have notified == true.
        // If the notification was not accepted, trap rather than emit a violating output.
        assert!(notified, "notification was not accepted");

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
